arguments.command:
cd /Users/adityabhargava/agency-lang/packages/agency-lang/runs/2026-07-31-171034-rCOYJf/inputs/gcode-to-text/workdir
awk '
/M486 S0/{print "S0 at line "NR}
/M486 S1/{print "S1 at line "NR}
/M486 S-1/{print "S-1 at line "NR}
/;.*[Zz]:/{}
' text.gcode > /tmp/transitions.txt
wc -l /tmp/transitions.txt
# get Z values right after each S0/S1 marker
python3 - <<'EOF'
import re
lines = open('text.gcode').readlines()
cur_z = None
events=[]
for i,l in enumerate(lines):
    l=l.strip()
    m = re.match(r'G1 .*Z([\-0-9.]+)', l)
    if m:
        cur_z = float(m.group(1))
    if l.startswith('M486 S'):
        events.append((i+1, l, cur_z))
for e in events:
    print(e)
EOF

